INSERT INTO "products" ("slug", "name", "tagline", "description", "category", "price_cents", "glyph", "tone") VALUES
('blameless-hoodie', 'Blameless Postmortem Hoodie', 'Heavyweight fleece, zero finger-pointing.', 'A 420gsm brushed-fleece hoodie printed with the five-whys ladder down the left sleeve. Kangaroo pocket fits a laptop charger and one very tired pager.', 'apparel', 6420, '5×WHY', '#d9562b'),
('works-on-my-machine-mug', 'Works On My Machine Mug', '14oz stoneware for localhost-grade confidence.', 'Glazed stoneware mug with a container diagram on one side and a shrug on the other. Dishwasher safe, unlike your staging environment.', 'desk', 1840, 'localhost', '#2f6f5e'),
('on-call-survival-kit', 'On-Call Survival Kit', 'Everything for the 3:12 a.m. page.', 'Eye mask, electrolyte tabs, a laminated escalation card, earplugs for the rest of the household, and a sticker that says "acknowledged." Packed in a zip pouch.', 'desk', 4275, 'SEV-2', '#b8872b'),
('kubectl-keycaps', 'kubectl Keycap Set', '14 PBT caps for the commands you type most.', 'Dye-sublimated PBT keycaps with get, apply, logs, describe, rollout and delete (in red, obviously). Cherry MX compatible, OEM profile.', 'hardware', 3690, 'k get po', '#3d5a80'),
('landing-zone-modules', 'Landing Zone Module Pack', '37 Terraform modules for a clean cloud baseline.', 'Opinionated Terraform modules for networking, IAM boundaries, logging buckets and budget alerts, with example stacks and a test harness. Lifetime updates, delivered as a zip download.', 'digital', 12900, 'tf plan', '#6b4e9b'),
('zero-downtime-course', 'Zero-Downtime Deploys Field Course', '11 hours on blue/green, canaries and rollbacks.', 'Video lessons and lab repositories that take one service from a single box to progressive delivery with automated rollback. Includes a certificate and the incident playbook template.', 'digital', 8900, 'canary 5%', '#2f6f5e'),
('status-degraded-stickers', 'Status: Degraded Sticker Pack', '9 vinyl stickers for laptops and pagers.', 'Matte vinyl stickers: Degraded, Partial Outage, All Systems Nominal, It''s DNS, Rollback Hero, and four more. Weatherproof and they come off cleanly.', 'apparel', 960, 'DEGRADED', '#c23b3b'),
('1u-desk-shelf', '1U Desk Shelf', 'A rack-mount aesthetic for your monitor stand.', 'Powder-coated steel shelf in 19-inch rack proportions with cage-nut holes that actually hold cable clips. Lifts a monitor 11cm and hides a USB hub.', 'hardware', 5730, '[ 1U ]', '#4a4a45'),
('runbook-field-notes', 'Runbook Field Notes (3-pack)', 'Grid notebooks with pre-printed incident timelines.', 'Pocket notebooks with a timeline template, a service map grid and a "things we tried" checklist on every spread. 48 pages each, lay-flat binding.', 'desk', 1425, 'T+00:04', '#b8872b'),
('chaos-gremlin-plush', 'Chaos Gremlin Plush', 'A soft reminder to test your failure modes.', 'A 23cm plush gremlin holding a tiny unplugged cable. Surprisingly good for tossing across the room during game days.', 'desk', 2780, 'kill -9', '#c23b3b'),
('ci-recipe-book', 'CI Recipe Book', '52 pipeline templates, copy-paste ready.', 'Workflow templates for build caching, matrix testing, container signing, preview environments and release tagging, each with notes on when not to use it. PDF and repository access.', 'digital', 4900, 'on: push', '#3d5a80'),
('build-light', 'USB Build Light', 'Green for passing, red for the whole team to see.', 'Aluminium USB-C status light with a tiny CLI and webhook listener. Configure it for pipelines, alerts or deploy windows. Includes a 2m braided cable.', 'hardware', 7450, '● PASS', '#2f6f5e');
